#!/usr/bin/env bash
#
# Free disk space taken by build outputs and temporary files. Everything
# removed is regenerated by the next build (`cargo build`, `npm run build`).
#
# Usage:
#   ./scripts/clean.sh               # Rust target/, frontend build caches, test outputs, logs
#   ./scripts/clean.sh --light       # only caches: Rust incremental + .svelte-kit (rebuilds stay fast)
#   ./scripts/clean.sh --all         # also node_modules/ (needs `npm install`) and uploads/
#   ./scripts/clean.sh -n            # dry run: show what would be removed and its size
#
# Never touched: releases/ (published client builds), .local/ (downloaded
# OpenVSCode), .sshx/ (session state), anything tracked by git.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

MODE="default"
DRY_RUN=0

usage() {
  sed -n '3,14p' "$0" | sed 's/^# \{0,1\}//'
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --light) MODE="light" ;;
    --all) MODE="all" ;;
    -n | --dry-run) DRY_RUN=1 ;;
    -h | --help) usage; exit 0 ;;
    *) echo "Unknown option: $1" >&2; usage >&2; exit 2 ;;
  esac
  shift
done

if [[ "$MODE" == "light" ]]; then
  TARGETS=(target/debug/incremental target/release/incremental .svelte-kit)
else
  TARGETS=(
    target            # Rust build output (the bulk, often > 10 GB)
    .svelte-kit       # SvelteKit generated files and cache
    build             # compiled frontend, served by sshx-server
    node_modules/.vite
    test-results
    playwright-report
    tests/e2e/test-results
    mprocs.log
  )
  # Packaging outputs (distribution/<platform>/dist/).
  for dir in distribution/*/dist; do
    [[ -d "$dir" ]] && TARGETS+=("$dir")
  done
  if [[ "$MODE" == "all" ]]; then
    TARGETS+=(
      node_modules    # reinstall with `npm install`
      uploads         # images pasted into sessions of a server run from here
    )
  fi
fi

# Size in KiB of the given paths (0 when none exist).
size_kib() {
  if [[ $# -eq 0 ]]; then echo 0; return; fi
  du -sk "$@" 2>/dev/null | awk '{s += $1} END {print s + 0}'
}

human() {
  awk -v k="$1" 'BEGIN {
    split("K M G T", u, " "); i = 1
    while (k >= 1024 && i < 4) { k /= 1024; i++ }
    printf (i == 1 ? "%d%s" : "%.1f%s"), k, u[i]
  }'
}

existing=()
for path in "${TARGETS[@]}"; do
  [[ -e "$path" ]] || continue
  # Safety net: never remove files git tracks.
  if [[ -n "$(git ls-files -- "$path" 2>/dev/null | head -1)" ]]; then
    echo "skip   $path (tracked by git)"
    continue
  fi
  existing+=("$path")
done

if [[ ${#existing[@]} -eq 0 ]]; then
  echo "Nothing to clean."
  exit 0
fi

total=0
for path in "${existing[@]}"; do
  kib=$(size_kib "$path")
  total=$((total + kib))
  printf '%-7s %8s  %s\n' "$([[ $DRY_RUN -eq 1 ]] && echo would || echo remove)" "$(human "$kib")" "$path"
  [[ $DRY_RUN -eq 1 ]] || rm -rf -- "$path"
done

if [[ $DRY_RUN -eq 1 ]]; then
  echo "Would free $(human "$total"). Run without -n to remove."
else
  echo "Freed $(human "$total")."
  if [[ " ${existing[*]} " == *" build "* ]]; then
    echo "Note: a running sshx-server serves build/; run \`npm run build\` before reloading it."
  fi
fi
